import{_ as t,H as s,c as i,b as n,a2 as a,K as r}from"./chunks/framework.BEqfOpL-.js";const d="/images/planner.webp",l="/images/planner_calendar.webp",f=JSON.parse('{"title":"Episode Planner","description":"The Episode Planner is your episode planning hub. Use Board to manage ideas, Calendar to plan dates, and AI Producer to discover topics. Open an episode to work on its own metadata and keywords.","frontmatter":{},"headers":[],"relativePath":"features/planner.md","filePath":"features/planner.md"}'),p={name:"features/planner.md"};function h(g,e,u,c,m,w){const o=s("HelpWalkthrough");return n(),i("div",null,[e[0]||(e[0]=a('<h1 id="episode-planner" tabindex="-1">Episode Planner <a class="header-anchor" href="#episode-planner" aria-label="Permalink to &quot;Episode Planner&quot;">​</a></h1><h2 id="plan-optimize-and-produce-episodes-strategically" tabindex="-1">Plan, Optimize, and Produce Episodes Strategically <a class="header-anchor" href="#plan-optimize-and-produce-episodes-strategically" aria-label="Permalink to &quot;Plan, Optimize, and Produce Episodes Strategically&quot;">​</a></h2><p>The Episode Planner is your episode planning hub. Use Board to manage ideas, Calendar to plan dates, and AI Producer to discover topics. Open an episode to work on its own metadata and keywords.</p><p><a href="/images/planner.webp" title="Open screenshot at full size"><img src="'+d+'" alt="Planner Dashboard" width="600px" style="display:block;margin:0 auto;"></a></p><p><strong>To access</strong>: In the sidebar, open <strong>Content → Episode Planner</strong>. Older guides called it the Planner tab of the Command Center.</p><h2 id="show-metadata-and-episode-metadata-are-separate" tabindex="-1">Show metadata and episode metadata are separate <a class="header-anchor" href="#show-metadata-and-episode-metadata-are-separate" aria-label="Permalink to &quot;Show metadata and episode metadata are separate&quot;">​</a></h2><p>The Planner focuses on <strong>episodes</strong>. Its <strong>Episodes → Keyword alignment</strong> card summarizes episode alignment. Open an episode to review its title, description, target keywords, and cover. If an episode has no separate cover, its analysis uses the show cover.</p><p>For your podcast&#39;s title, author, description, show cover, and show-keyword ranking summary, open <strong>Content → <a href="/features/show-optimization.html">Show Optimization</a></strong>.</p><h2 id="board-tab" tabindex="-1"><strong>Board Tab</strong> <a class="header-anchor" href="#board-tab" aria-label="Permalink to &quot;**Board Tab**&quot;">​</a></h2><p>The Board provides a kanban-style view for managing your episode pipeline.</p><h3 id="columns" tabindex="-1"><strong>Columns</strong> <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;**Columns**&quot;">​</a></h3><ul><li><strong>Ideas</strong> — Episode concepts you&#39;re considering. Add ideas manually or import them from the AI Producer.</li><li><strong>In Progress</strong> — Episodes you&#39;re actively working on. When you move a card here, you can ask PodSEO for AI-powered title and description suggestions aligned with your keyword strategy.</li><li><strong>Published</strong> — Episodes that have been released. Published episodes can be analyzed individually for keyword alignment — unlike the previous system that only analyzed the last 4 episodes, you can now review any episode on your board.</li></ul><h3 id="working-with-cards" tabindex="-1"><strong>Working with Cards</strong> <a class="header-anchor" href="#working-with-cards" aria-label="Permalink to &quot;**Working with Cards**&quot;">​</a></h3><ul><li><strong>Add ideas</strong> using the &quot;+ Add Idea&quot; button</li><li><strong>Move cards</strong> between columns as episodes progress through your workflow</li><li><strong>Get AI suggestions</strong> for title and description when an episode is in progress</li><li><strong>Link to feed</strong> — Connect planned episodes to published feed entries</li></ul><h3 id="reuse-and-reschedule-episodes" tabindex="-1">Reuse and reschedule episodes <a class="header-anchor" href="#reuse-and-reschedule-episodes" aria-label="Permalink to &quot;Reuse and reschedule episodes&quot;">​</a></h3><p>Open a card to see the actions available for its current stage:</p><ul><li><strong>Duplicate</strong> copies an episode into a new plan you can adapt.</li><li><strong>Plan Follow-up</strong> creates the next episode based on the existing schedule; it appears for published episodes and dated episodes in progress.</li><li><strong>Reschedule</strong> moves an overdue planned date to today. Edit the date when you need a different day.</li><li><strong>Delete</strong> removes an unused idea from the board; <strong>Archive</strong> hides eligible episodes you no longer want in the active pipeline. These actions do not delete audio from your host.</li></ul><p>Published or linked episodes cannot be archived directly. Review the connection and use <strong>Unlink</strong> first if you need to separate the plan from its feed episode. Unlinking does not remove the published episode from listening platforms.</p><h3 id="target-keywords-for-an-individual-episode" tabindex="-1">Target keywords for an individual episode <a class="header-anchor" href="#target-keywords-for-an-individual-episode" aria-label="Permalink to &quot;Target keywords for an individual episode&quot;">​</a></h3><p>Episode keyword targets are available on every plan, including Free. Guest names are tracked but not scored.</p><p>The episode&#39;s SEO score and title alignment use these keywords; until the episode has its own, they use your show keywords, or your Unassigned keywords if no show keywords are set.</p><p>The panel also shows the episode&#39;s <strong>Search opportunity</strong> per platform, and <strong>Suggest a title</strong> opens LUCIA to ask for title ideas based on the episode&#39;s keywords; review its suggestions before updating your episode. Free plans do not include AI episode suggestions.</p><ol><li>Open an episode in progress and add a topic in <strong>Keywords for this episode</strong>.</li><li>Add a guest name separately with <strong>It&#39;s a guest&#39;s name</strong> selected.</li><li>Review its <strong>SEO Score</strong> and <strong>Search opportunity</strong>. An unavailable estimate is not a zero.</li><li>Once the episode is published through your host, choose its matching entry under <strong>Link to published episode</strong>. Check its title and date first.</li></ol>',23)),r(o,{src:"/walkthroughs/planner-episode.webp",poster:"/images/planner_episode_keywords.webp",alt:"Add an episode topic and guest, review alignment and search opportunity, then link the plan to its published episode",duration:29650,autoplay:"",loop:"",sample:""}),e[1]||(e[1]=a('<p>Use <strong>Unlink</strong> to correct a connection. Linking or marking a card Published does not upload audio or distribute an episode.</p><p>For client sign-off, see <a href="/features/agency-workspace.html#request-episode-and-social-post-approvals">Agency approvals</a>. A required approval covers the submitted version; changing the content can require a new review.</p><h2 id="calendar-tab" tabindex="-1"><strong>Calendar Tab</strong> <a class="header-anchor" href="#calendar-tab" aria-label="Permalink to &quot;**Calendar Tab**&quot;">​</a></h2><p>The Calendar view shows your episodes on a timeline, helping you visualize your publishing cadence.</p><ul><li><strong>Month view</strong> — See all episodes in a traditional calendar grid</li><li><strong>Timeline view</strong> — A linear view of episode dates for planning ahead</li></ul><p><a href="/images/planner_calendar.webp" title="Open screenshot at full size"><img src="'+l+'" alt="Planner Calendar view"></a></p><p>Use the Calendar to maintain a consistent publishing schedule, which is an important factor in platform algorithms and listener retention.</p><h2 id="ai-producer-tab" tabindex="-1"><strong>AI Producer Tab</strong> <a class="header-anchor" href="#ai-producer-tab" aria-label="Permalink to &quot;**AI Producer Tab**&quot;">​</a></h2><p>The AI Producer helps you discover new episode topics and content opportunities.</p><h3 id="what-it-analyzes" tabindex="-1"><strong>What It Analyzes</strong> <a class="header-anchor" href="#what-it-analyzes" aria-label="Permalink to &quot;**What It Analyzes**&quot;">​</a></h3><ul><li><strong>Trending topics</strong> — What&#39;s gaining attention in your podcast&#39;s niche right now</li><li><strong>Content gaps</strong> — Topics your competitors cover that you haven&#39;t addressed yet</li><li><strong>Keyword opportunities</strong> — Keywords with growth potential based on your strategy and rankings</li><li><strong>Optimal publishing timing</strong> — Scheduling guidance that helps you turn your release cadence into a strategic advantage</li></ul><h3 id="from-ideas-to-board" tabindex="-1"><strong>From Ideas to Board</strong> <a class="header-anchor" href="#from-ideas-to-board" aria-label="Permalink to &quot;**From Ideas to Board**&quot;">​</a></h3><p>When the AI Producer suggests a topic, click <strong>Create Episode</strong> to add it to your Board as a new episode plan, with the suggested angle saved in its notes. This creates a seamless flow from discovery to planning to production.</p><h2 id="social-clips" tabindex="-1"><strong>Social clips</strong> <a class="header-anchor" href="#social-clips" aria-label="Permalink to &quot;**Social clips**&quot;">​</a></h2><p>Social clips have their own page: open <strong>Promote → Social</strong> in the sidebar. There you can turn your episodes into short video reels — surface an episode&#39;s best moments, generate vertical clips, and publish them to connected social destinations — YouTube Shorts, LinkedIn, Bluesky, Instagram, Threads, Facebook, and TikTok (paid plans).</p><p>For a full walkthrough, see the <a href="/features/social-publishing.html">Social</a> article.</p><h2 id="the-planning-workflow" tabindex="-1"><strong>The Planning Workflow</strong> <a class="header-anchor" href="#the-planning-workflow" aria-label="Permalink to &quot;**The Planning Workflow**&quot;">​</a></h2><p>The Planner supports a complete episode planning cycle:</p><ol><li><strong>Review show setup</strong> — Use Positioning, Keyword Strategy, and <a href="/features/show-optimization.html">Show optimization</a> for your podcast as a whole.</li><li><strong>Discover topics</strong> — Review AI Producer or Topics (Pulse) for relevant episode ideas.</li><li><strong>Plan episodes</strong> — Add ideas to the Board and choose dates in Calendar.</li><li><strong>Choose episode keywords</strong> — Open an episode and set its targets in <strong>Keywords for this episode</strong>.</li><li><strong>Optimize and publish</strong> — Review the episode&#39;s title, description, and cover. Publish through your podcast host, then link the plan to its feed episode.</li><li><strong>Track results</strong> — Open <strong>Search Visibility → Rankings → Episodes</strong>, or compare listening data in <strong>Analytics → Episodes</strong> for a source.</li></ol><h2 id="integration-with-other-features" tabindex="-1"><strong>Integration with Other Features</strong> <a class="header-anchor" href="#integration-with-other-features" aria-label="Permalink to &quot;**Integration with Other Features**&quot;">​</a></h2><ul><li><strong><a href="/features/keyword-strategy.html">Keyword Strategy</a></strong> — Your show and episode keywords drive the alignment scores and AI suggestions</li><li><strong><a href="/features/positioning.html">Positioning</a></strong> — Your strategic positioning informs the AI Producer&#39;s topic recommendations</li><li><strong><a href="/features/competitive-analysis.html">Competitive Analysis</a></strong> — Competitor data feeds into content gap analysis</li><li><strong><a href="/features/show-rankings.html">Show Rankings</a></strong> and <strong><a href="/features/keyword-tracker.html">Keyword Tracker</a></strong> — Track the impact of your optimization efforts</li></ul><h2 id="availability" tabindex="-1"><strong>Availability</strong> <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;**Availability**&quot;">​</a></h2><p>The Board and Calendar are available to all users. On the free plan, the Board can hold up to 3 active planned episodes at a time; paid plans are effectively unlimited. The AI Producer and AI-powered suggestions require a paid plan.</p><hr><h3 id="pro-tips" tabindex="-1"><strong>Pro Tips</strong> <a class="header-anchor" href="#pro-tips" aria-label="Permalink to &quot;**Pro Tips**&quot;">​</a></h3><ul><li>Review an episode&#39;s keyword alignment after changing its target keywords or metadata</li><li>Use the AI Producer regularly to keep your content pipeline full of strategically relevant ideas</li><li>Don&#39;t optimize all metadata at once — make changes incrementally so you can track what&#39;s driving ranking improvements</li><li>Show keywords are for show-level metadata (title, description), while episode keywords guide each episode&#39;s title and description</li><li>Plan in batches of 5-10 episodes aligned with your current keyword strategy, then evaluate results before adjusting</li></ul><p>The Planner brings together planning, optimization, and content discovery into a single workflow, helping you create episodes that are both valuable to your audience and optimized for discoverability.</p>',27))])}const b=t(p,[["render",h]]);export{f as __pageData,b as default};
